pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        address from = address(0x1);
        address caddress = address(0x2);
        address[] memory tos = new address[](1);
        tos[0] = address(0x3);
        uint[] memory values = new uint[](1);
        values[0] = 100;

        bool result;
        try c.transfer(from, caddress, tos, values) {
            result = true;
        } catch {
            result = false;
        }

        // Reference returns true; buggy returns false
        assertTrue(result == true);
    }
}

